resumer <- function(x) {
  presents <- x[!is.na(x)]
  if (length(presents) == 0) return(c(n = 0, moyenne = NA))
  c(n = length(presents), moyenne = mean(presents))
}
resumer(c(10, NA, 30)) # n = 2 ; moyenne = 20

resumer <- function(x) {
  if (length(x) < 2) stop("Au moins deux valeurs")
  c(n=length(x), moyenne=mean(x), sd=sd(x))
}
resumer(c(10,20,30,40))
m <- matrix(c(10,20,30,40,50,60), nrow=2, byrow=TRUE)
apply(m, 1, mean)          # 20 et 50
for (i in seq_len(nrow(m))) {
  print(mean(m[i, ]))
}
